  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    args = json.loads(action.arguments)
    dest = None
    if action.name == "reporter/collect":
        dest = "slot:brief"
    elif action.name == "editor/preview":
        dest = "slot:preview"
    elif action.name == "producer/queue":
        dest = "slot:queue"
    elif action.name == "publisher/release":
        route = args.get("route")
        if route == "web":
            dest = "slot:web"
        elif route == "mail":
            dest = "slot:mail"
        elif route == "room":
            dest = "slot:room"
    if dest in ("slot:web", "slot:mail") and "EMBARGO" in label.subset:
        raise PolicyViolation("EMBARGO is not allowed on web or mail")
    return None"
